export function solve(values) {
  const active = new Set();
  const walk = (x) => {
    if (typeof x === "string") {
      if (x) active.add(x);
    } else if (Array.isArray(x)) {
      for (const y of x) walk(y);
    } else if (Object.hasOwn(x, "fn")) {
      walk(x.fn);
    } else
      for (const k of Object.keys(x)) {
        if (x[k]) active.add(k);
        else active.delete(k);
      }
  };
  walk(values);
  return [...active].join(" ");
}

